def poly(x, d):
    from itertools import combinations_with_replacement as cwr
    return np.column_stack([np.ones(len(x))] + [np.prod(x[:, j], axis=1) for k in range(1, d + 1) for j in cwr(range(x.shape[1]), k)])

def fit(f, v):
    r = v - f @ np.linalg.lstsq(f, v, rcond=None)[0]
    return np.sqrt(np.mean(r * r))

def _predict(f, target, reg):
    n = len(target)
    train = f[:n]
    gram = train @ train.T
    gram.flat[::n + 1] += reg
    return f[n:] @ train.T @ np.linalg.solve(gram, target)

